 "content": "def transform(grid):
    """Fill below each top-row V-shaped pair of diagonal 6 markers with 2."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    # Each top-row marker is the apex of a V whose sides descend one
    # column left/right per row. Fill the strict interior between sides.
    for apex in range(w):
        if grid[0][apex] != 6:
            continue
        for r in range(1, h):
            left, right = apex - r, apex + r
            for c in range(max(0, left + 1), min(w - 1, right - 1) + 1):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out
